let authToken='',booting=false,signatureRole='person';const recordCache=new Map();
let session,office={},records=[],local=[],view='home',draft=null,step=0,users=[],signaturePoints=[],drawing=false,currentStroke=[],autosaveTimer,syncing=false,ccoTimer,previousNew=null,audioEnabled=false;
