function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',6000)}
async function api(path,method='GET',data){if(!window.DER_CONFIG?.endpoint||window.DER_CONFIG.endpoint.includes('__'))throw Error('Servidor ainda em configuração.');const response=await fetch(window.DER_CONFIG.endpoint,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({path,method,data,token:authToken}),redirect:'follow'});const result=await response.json();if(!result.ok){const err=Error(result.error||'Não foi possível concluir.');err.status=result.status||400;throw err}if(method!=='GET')recordCache.clear();if(result.data?.token){authToken=result.data.token;await dbPut('meta',authToken,'auth-token')}return result.data}

const dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('der-notifica-v1',1);r.onupgradeneeded=()=>{const d=r.result;d.createObjectStore('meta');d.createObjectStore('records',{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
async function dbGet(store,key){const db=await dbPromise;return new Promise((resolve,reject)=>{const r=db.transaction(store).objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function dbPut(store,value,key){const db=await dbPromise;return new Promise((resolve,reject)=>{const t=db.transaction(store,'readwrite');if(key===undefined)t.objectStore(store).put(value);else t.objectStore(store).put(value,key);t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)})}
async function dbDelete(store,key){const db=await dbPromise;return new Promise((resolve,reject)=>{const t=db.transaction(store,'readwrite');t.objectStore(store).delete(key);t.oncomplete=resolve;t.onerror=()=>reject(t.error)})}
async function loadLocal(){const db=await dbPromise;const all=await new Promise((resolve,reject)=>{const r=db.transaction('records').objectStore('records').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});local=all.filter(r=>r.owner===session?.user.userId);updateConnection()}
function updateConnection(){const pending=local.filter(r=>r.localStatus==='pending').length;$('#pending-count').textContent=pending?'('+pending+')':'';$('#connection').textContent=navigator.onLine?'● Online':'● Sem conexão';$('#connection').className='badge'+(navigator.onLine?'':' warn')}
async function boot(){
 authToken=await dbGet('meta','auth-token')||'';updateConnection();
 if('serviceWorker'in navigator&&navigator.onLine){
 const verify=async()=>{try{const reg=await navigator.serviceWorker.ready,target=navigator.serviceWorker.controller||reg.active;if(!target)return;const result=await new Promise((resolve,reject)=>{const channel=new MessageChannel(),timer=setTimeout(()=>reject(Error('Preparo offline ainda em andamento.')),5000);channel.port1.onmessage=e=>{clearTimeout(timer);resolve(e.data)};target.postMessage({type:'OFFLINE_STATUS'},[channel.port2])});await dbPut('meta',!!result.ready,'shell-ready');if(view==='offline')await offlinePage()}catch(e){console.warn(e.message)}};
 dbPut('meta',false,'shell-ready');navigator.serviceWorker.addEventListener('controllerchange',verify);navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(async reg=>{await reg.update();await verify()}).catch(e=>console.warn('Não foi possível preparar o uso offline:',e.message));
 }
 let cachedRendered=false;const cached=await dbGet('meta','session');if(cached?.user&&authToken&&new Date(cached.offlineUntil)>new Date()){session=cached;$('#identity').innerHTML='<strong>'+esc(session.user.name)+'</strong><br>'+esc(session.user.email)+'<br>'+esc(session.user.unit)+' · '+esc(session.user.affiliation);office=await dbGet('meta','office:'+session.user.userId)||{};await loadLocal();setupNav();booting=true;try{await navigate(ccoOnly?(can('cco')?'cco':'alerts'):location.hash.slice(1)||'home');cachedRendered=true}finally{booting=false}}
 try{session=await api('me');await dbPut('meta',session,'session');office=await api('settings');await dbPut('meta',office,'office:'+session.user.userId)}catch(e){if(!navigator.onLine||![401,403].includes(e.status)){session=await dbGet('meta','session');if(!session||!lease())return access('Conecte-se para validar seu acesso. O período offline é de até 7 dias.');office=await dbGet('meta','office:'+session.user.userId)||{};toast('Modo offline: os registros serão guardados neste aparelho.')}else return access(e.message)}
 $('#identity').innerHTML='<strong>'+esc(session.user.name)+'</strong><br>'+esc(session.user.email)+'<br>'+esc(session.user.unit)+' · '+esc(session.user.affiliation);
 await loadLocal();setupNav();if(ccoOnly&&!can('cco')&&!can('readAlerts'))return access('Seu e-mail não possui permissão para operar o CCO.');if(!cachedRendered||['home','mine','cco','offline'].includes(view))await navigate(ccoOnly?(can('cco')?'cco':'alerts'):location.hash.slice(1)||'home');if(navigator.onLine&&local.some(r=>r.localStatus==='pending'))syncQueue(false);navigator.storage?.persist?.();startNotices();
}
function access(message){$('#nav').innerHTML='';$('#identity').textContent='Acesso restrito por e-mail autorizado';$('#sync').disabled=true;$('#main').innerHTML='<div class="access"><img src="./logo-der.jpg" alt="DER"><span class="eyebrow" style="display:block;margin-top:25px">ACESSO AUTORIZADO</span><h1>'+ (ccoOnly?'Central de Alertas CCO':'DER Notifica') +'</h1><p class="muted">'+esc(message)+'</p><form id="login-form" class="panel" style="text-align:left;margin-top:25px"><label>E-mail autorizado<input name="email" type="email" required autocomplete="email"></label><button type="button" id="request-code" class="primary" style="width:100%;margin:15px 0">Receber código por e-mail</button><label>Código de acesso<input name="code" inputmode="numeric" pattern="[0-9]{8}" maxlength="8" placeholder="8 dígitos" autocomplete="one-time-code"></label><label class="check" style="margin-top:18px"><input name="remember" type="checkbox" checked>Manter conectado neste aparelho por 7 dias</label><button class="yellow" style="width:100%;margin-top:15px">Entrar →</button><p class="muted" id="login-message">Use o mesmo e-mail cadastrado pelo administrador.</p></form><button id="install-login">Instalar aplicativo</button></div>';$('#request-code').onclick=async()=>{const form=$('#login-form');if(!form.email.checkValidity())return form.email.reportValidity();$('#request-code').disabled=true;try{const p=await api('login/request','POST',{email:form.email.value});$('#login-message').textContent=p.message;form.code.focus()}catch(e){$('#login-message').textContent=e.message}finally{$('#request-code').disabled=false}};$('#login-form').onsubmit=async e=>{e.preventDefault();const form=e.target;try{const p=await api('login/verify','POST',{email:form.email.value,code:form.code.value,remember:form.remember.checked});authToken=p.token;await dbPut('meta',authToken,'auth-token');await dbPut('meta',p,'session');location.reload()}catch(err){$('#login-message').textContent=err.message}};$('#install-login').onclick=installApp;}

function setupNav(){if(ccoOnly){$('#nav').innerHTML='';return}const list=[['home','⌂','Início',true],['new','▤','Notificar',can('notify')||can('embargo')],['history','≡','Histórico de notificações',can('history')],['mine','◷','Minhas notificações',can('notify')||can('embargo')],['alert','⚑','Enviar Alerta CCO',can('alert')],['my-alerts','◷','Meus alertas',can('alert')],['alert-history','≡','Histórico de alertas',can('readAlerts')||can('cco')],['alerts','▦','Acompanhar alertas',can('readAlerts')&&!can('cco')],['cco','▦','Painel CCO',can('cco')],['offline','⇅','Neste aparelho',true],['admin','⚙','Acessos e ajustes',can('admin')],['deletions','⌫','Solicitações de exclusão',can('deleteRecords')],['help','?','Como usar',true]];$('#nav').innerHTML=list.filter(x=>x[3]).map(x=>'<button data-nav="'+x[0]+'"><span class="nav-icon">'+x[1]+'</span>'+x[2]+'</button>').join('');$$('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));}

function head(eyebrow,title,text,action=''){return '<div class="page-head"><div><span class="eyebrow">'+eyebrow+'</span><h1>'+title+'</h1><p>'+text+'</p></div>'+action+'</div>'}
async function navigate(next){closeMenu();if(ccoOnly)next=can('cco')?'cco':'alerts';if(draft&&view==='form'){collect();await saveDraft();}clearInterval(ccoTimer);if(next!=='cco')document.body.classList.remove('monitor');view=next;location.hash=next;$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===next||(next==='form'&&b.dataset.nav==='new')));$('#main').setAttribute('aria-busy','true');try{
 if(next==='new')return newRecord('access');if(next==='alert')return newRecord('alert');
 if(next.startsWith('record/')){await history('my-alerts');await openRecord(next.slice(7));return}if(next==='deletions')await deletionRequestsPage();else if(next==='home')await home();else if(['history','mine','my-alerts','alert-history'].includes(next))await history(next);else if(next==='offline')await offlinePage();else if(next==='cco'||next==='alerts')await cco(next==='alerts');else if(next==='admin')await admin();else if(next==='help')help();else if(next==='form'&&draft)renderForm();else await home();
 }catch(e){toast(e.message);$('#main').innerHTML=head('DER NOTIFICA','Não foi possível carregar',esc(e.message))+'<button data-retry> Tentar novamente </button>'; $('[data-retry]').onclick=()=>navigate(next)}finally{$('#main').setAttribute('aria-busy','false')}window.scrollTo(0,0)}
async function fetchRecords(scope='mine'){if(booting)return [];if(!navigator.onLine)return [];const cached=recordCache.get(scope),reusable=!['cco','alerts'].includes(scope);if(reusable&&cached&&Date.now()-cached.at<15000)return cached.rows;const data=await api('records?scope='+scope);await purgeDeletedRecords(data.deletedIds||[]);recordCache.set(scope,{rows:data.records,at:Date.now()});return data.records}
