async function home(){const rows=await fetchRecords('mine');records=merged(rows);const pending=local.filter(r=>r.localStatus==='pending').length;$('#main').innerHTML=head('FISCALIZAÇÃO E OPERAÇÃO','Seu trabalho começa no trecho.','Registre, comunique e acompanhe cada ocorrência.')+'<section class="hero"><div><span class="eyebrow">DER NOTIFICA</span><h2>O que você encontra no campo<br>vira ação acompanhada.</h2><p>Notificações, evidências e comunicação com o CCO em um só lugar, mesmo quando o trecho fica sem sinal.</p></div><button class="yellow" id="hero-new">＋ Novo registro</button></section><div class="stats">'+stat('MEUS REGISTROS',records.filter(r=>r.localStatus!=='draft').length,'Autoria identificada')+stat('NESTE APARELHO',pending,'Aguardando sincronização')+stat('CIÊNCIA PENDENTE',records.filter(r=>r.status==='Ciência pendente').length,'Visitas e tentativas registradas')+stat('ALERTAS ENVIADOS',rows.filter(r=>r.kind==='alert').length,'Recebidos pelo sistema')+'</div><div class="section-head"><h2>Ações de campo</h2><span class="note-label">Escolha o fluxo de trabalho</span></div><div class="cards">'+(can('inspect')||can('notify')?card('▤','Notificação de acesso','Registre o acesso rodoviário, identifique o lindeiro e acompanhe a ciência.','Notificar acesso →','access')+card('▤','Notificação de ocupação','Documente a ocupação da faixa de domínio e a providência determinada.','Notificar ocupação →','occupation'):'')+(can('embargo')?card('⊘','Ordem de embargo','Documente a obra ou serviço e registre a ciência do responsável.','Preparar embargo →','embargo'):'')+(can('alert')?card('⚑','Alerta CCO','Fotos e localização para avaliação operacional da central.','Comunicar ocorrência →','alert'):'')+'</div><div class="section-head"><h2>Últimos registros</h2><button class="small" id="all-mine">Ver meus registros →</button></div>'+table(records.slice(0,5))+(!office.approved&&can('admin')?'<div class="notice">Antes de emitir documentos, confira os contatos da unidade e aprove os modelos em <strong>Acessos e ajustes</strong>.</div>':'');$('#hero-new').onclick=()=>navigate(can('inspect')||can('notify')?'new':'alert');$('#all-mine').onclick=()=>navigate('mine');bindCards();bindRows();}
function stat(label,note,small){return '<div class="stat"><span class="label">'+label+'</span><span class="num">'+note+'</span><small>'+small+'</small></div>'}
