function table(rows){return rows.length?'<div class="panel table-wrap" style="padding:0"><table><thead><tr><th>Registro</th><th>Localização</th><th>Responsável / autor</th><th>Situação</th><th>Data</th><th></th></tr></thead><tbody>'+rows.map(r=>'<tr data-id="'+r.id+'"><td><strong>'+esc(r.protocol||'LOCAL · '+r.id.slice(0,8).toUpperCase())+'</strong><small>'+esc(KIND[r.kind])+'</small></td><td><strong>'+esc(r.road||'Rodovia pendente')+' · km '+esc(r.km||'—')+'</strong><small>'+esc(r.direction||'')+' '+esc(r.side||'')+'</small></td><td>'+esc(r.kind==='alert'?r.category:r.person||'—')+'<small>'+esc(r.creatorName||session.user.name)+'</small></td><td>'+badge(r)+'</td><td>'+fmt(r.createdAt)+'</td><td>'+(can('pdf')&&r.localStatus!=='draft'?'<button class="small" data-pdf-id="'+r.id+'" aria-label="Baixar PDF de '+esc(r.protocol||'registro local')+'">↓ PDF</button>':'↗')+'</td></tr>').join('')+'</tbody></table></div>':'<div class="empty"><strong>Nenhum registro por aqui.</strong>Os registros aparecerão nesta lista conforme forem criados.</div>'}
