async function newRecord(kind){const allowed=kind==='alert'?can('alert'):kind==='embargo'?can('embargo'):can('notify')||can('inspect');if(!allowed)return toast('Seu perfil não permite criar esse registro.');if(!lease())return toast('Conecte-se para renovar sua autorização de uso offline.');const old=local.find(r=>r.localStatus==='draft'&&r.kind===kind);if(old){draft=structuredClone(old);toast('Seu rascunho anterior foi retomado.')}else{draft={id:crypto.randomUUID(),kind:kind==='access'&&!can('notify')?'inspection':kind,owner:session.user.userId,createdAt:new Date().toISOString(),occurredAt:new Date().toISOString(),creatorName:session.user.name,creatorEmail:session.user.email,unit:session.user.unit,road:'SP-',km:'',side:'Direito',direction:'Crescente',visit:'Encontrado',delivery:'Digital / impressão',measure:'Desocupar a faixa de domínio',days:'',risk:'Moderado',category:'Sinalização danificada',contactPhone:session.user.phone||'',agentSigner:session.user.name||'',attachments:[],localStatus:'draft'};}step=0;view='form';location.hash='form';renderForm();await saveDraft();}
