const select=(name,label,options,full=false)=>'<label class="'+(full?'full':'')+'">'+label+'<select name="'+name+'">'+options.map(o=>'<option value="'+esc(Array.isArray(o)?o[0]:o)+'" '+(draft[name]===(Array.isArray(o)?o[0]:o)?'selected':'')+'>'+esc(Array.isArray(o)?o[1]:o)+'</option>').join('')+'</select></label>';
