async function deletionRequestsPage(inModal=false){if(!can('deleteRecords'))return toast('Análise de exclusões não autorizada.');if(!navigator.onLine)return toast('Conecte-se para consultar as solicitações.');const result=await api('deletion-requests'+(ccoOnly?'?scope=alerts':''));const html=head('CONTROLE DE REGISTROS','Solicitações de exclusão','Analise o motivo e confirme a decisão. O registro permanece disponível enquanto o pedido estiver pendente.')+(result.records.length?result.records.map(r=>'<section class="panel"><h3>'+esc(r.protocol)+' · '+esc(KIND[r.kind])+'</h3><p>'+esc(r.road)+' · km '+esc(r.km)+'</p>'+r.deletionRequests.filter(x=>x.status==='Pendente').map(x=>'<p><strong>'+esc(x.requesterName)+'</strong> · '+esc(x.requesterEmail)+' · '+fmt(x.requestedAt)+'</p><p>'+esc(x.reason)+'</p><div class="actions"><button data-review="'+r.id+'" data-request="'+x.id+'" data-action="approve">Aprovar exclusão</button><button data-review="'+r.id+'" data-request="'+x.id+'" data-action="reject">Recusar</button><button data-open-deletion="'+r.id+'">Abrir registro</button></div>').join('')+'</section>').join(''):'<div class="empty">Nenhuma solicitação de exclusão pendente.</div>');if(inModal){$('#modal-body').innerHTML=html;$('#modal').showModal()}else $('#main').innerHTML=html;$$('[data-review]').forEach(b=>b.onclick=()=>deletionDialog(result.records.find(r=>r.id===b.dataset.review),b.dataset.action,b.dataset.request));$$('[data-open-deletion]').forEach(b=>b.onclick=()=>openRecord(b.dataset.openDeletion));}

function ccoColumnRows(rows,status){const selected=rows.filter(r=>r.status===status);return status==='Encerrado'?selected.sort((a,b)=>(b.closedAt||b.statusUpdatedAt||b.receivedAt).localeCompare(a.closedAt||a.statusUpdatedAt||a.receivedAt)||b.id.localeCompare(a.id)).slice(0,5):selected;}
async function openClosedAlerts(){if(!navigator.onLine)return toast('Conecte-se para consultar os encerrados.');$('#modal-body').innerHTML='<span class="eyebrow">ARQUIVO OPERACIONAL</span><h2>Consultar encerrados</h2><p class="muted">Pesquise todos os alertas encerrados. O período considera a data de encerramento.</p><form id="closed-search"><div class="form-grid"><label class="full">Pesquisar<input name="search" placeholder="Protocolo, rodovia, km, agente ou ocorrência"></label><label>Encerrado de<input name="from" type="date"></label><label>Até<input name="to" type="date"></label></div><button class="primary" style="margin:18px 0">Consultar</button></form><div id="closed-results" aria-live="polite"></div>';$('#modal').showModal();const form=$('#closed-search');let query={search:'',from:'',to:''},sequence=0;const load=async(page=1)=>{const current=++sequence;$('#closed-results').textContent='Consultando encerrados…';try{const params=new URLSearchParams({...query,page});const result=await api('cco-closed?'+params);if(current!==sequence||!$('#closed-results'))return;$('#closed-results').innerHTML='<p class="muted">'+result.total+' alerta(s) encerrado(s) · Página '+result.page+' de '+result.pages+'</p>'+(result.records.length?'<div class="closed-list">'+result.records.map(r=>'<button class="closed-result" data-closed-id="'+r.id+'"><strong>'+esc(r.road)+' · km '+esc(r.km)+'</strong><span>'+esc(r.protocol)+' · '+esc(r.category)+'</span><span>Encerrado em '+fmt(r.closedAt)+'</span><small>'+esc(r.creatorName)+' · Abrir registro ↗</small></button>').join('')+'</div>':'<div class="empty">Nenhum encerrado encontrado com estes filtros.</div>')+'<div class="actions"><button id="closed-prev" '+(result.page<=1?'disabled':'')+'>← Anteriores</button><button id="closed-next" '+(result.page>=result.pages?'disabled':'')+'>Próximos →</button></div>';$$('[data-closed-id]').forEach(b=>b.onclick=()=>openRecord(b.dataset.closedId));$('#closed-prev').onclick=()=>load(result.page-1);$('#closed-next').onclick=()=>load(result.page+1)}catch(error){if($('#closed-results'))$('#closed-results').textContent=error.message}};form.onsubmit=e=>{e.preventDefault();query=Object.fromEntries(new FormData(form));load(1)};await load(1);}
